import boto3, yaml

with open('/home/ubuntu/.agent-ml-be-backup.yaml') as f:
    creds = yaml.safe_load(f)

s3 = boto3.client('s3',
    aws_access_key_id=[REDACTED]'aws_access_key_id'],
    aws_secret_access_key=[REDACTED]'aws_secret_access_key'],
    region_name=creds.get('region', 'us-east-1')
)

bucket = 'agent-ml-manager-backups-emnlp'

# Try known prefixes for both servers
for server in ['westb-23072', 'westd-32935']:
    print(f'=== {server} ===')
    for i in range(60):
        key = f'recovery_aware_struct_prune/{server}/checkpoint_{i:03d}.tar'
        try:
            resp = s3.head_object(Bucket=bucket, Key=key)
            size_mb = resp['ContentLength'] / (1024**2)
            size_gb = resp['ContentLength'] / (1024**3)
            if size_gb >= 1:
                print(f'  {key}: {size_gb:.2f} GB')
            else:
                print(f'  {key}: {size_mb:.1f} MB')
        except s3.exceptions.ClientError as e:
            if e.response['Error']['Code'] == '404':
                break
            else:
                print(f'  {key}: {e}')
                break
    # Also try without numbering
    for suffix in ['checkpoints.tar', 'all_checkpoints.tar', 'checkpoint_000.tar']:
        key = f'recovery_aware_struct_prune/{server}/{suffix}'
        try:
            resp = s3.head_object(Bucket=bucket, Key=key)
            size_gb = resp['ContentLength'] / (1024**3)
            print(f'  {key}: {size_gb:.2f} GB')
        except:
            pass
